  if board[16+3*(y-5),16+3*(x-5)]!=5:
   G[x,y]=[(a,b) for a,b in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)] if 5<=a<16 and 5<=b<16 and board[16+3*(b-5),16+3*(a-5)]!=5]
def comp(s):
 seen={s}; q=[s]
 for u in q:
  for v in G[u]:
   if v not in seen:seen.add(v);q.append(v)
 return seen
