from collections import deque
start=(5,15); goal=(9,5)
prev={start:None};pq=deque([start]);act={}
dirs={(1,0):4,(-1,0):3,(0,1):2,(0,-1):1}
for u in list(pq): pass
while pq:
 u=pq.popleft()
 if u==goal:break
 for v in G[u]:
  # only endpoints non2, connector 2; skip moving onto red from red irrelevant BFS fine
  if v not in prev:
   prev[v]=u;act[v]=dirs[v[0]-u[0],v[1]-u[1]];pq.append(v)
path=[];cur=goal
while cur!=start:path.append((act[cur],cur));cur=prev[cur]
path=path[::-1]
